from concurrent.futures import ThreadPoolExecutor
from threading import Barrier, Condition, Event
from cachetools import cached, cachedmethod, LRUCache

# Instance-local synchronization does not conflate identical method keys.
gate = Barrier(2)
class Independent:
    __hash__ = None
    def __init__(self):
        self.cache = {}
        self.condition = Condition()
    @cachedmethod(lambda self: self.cache, condition=lambda self: self.condition)
    def get(self, k):
        gate.wait(3)
        return id(self)
a, b = Independent(), Independent()
with ThreadPoolExecutor(2) as pool:
    x, y = pool.submit(a.get, 1), pool.submit(b.get, 1)
    assert x.result(5) == id(a) and y.result(5) == id(b)

# Clearing an in-flight computation must not remove its pending marker.
for info in (False, True):
    started, release = Event(), Event()
    @cached({}, condition=Condition(), info=info)
    def f(k):
        started.set()
        assert release.wait(3)
        return k
    with ThreadPoolExecutor(2) as pool:
        first = pool.submit(f, 1)
        assert started.wait(3)
        second = pool.submit(f, 1)
        f.cache_clear()
        release.set()
        assert first.result(5) == second.result(5) == 1

# Methods notify on failure and on values too large to cache.
for cache in ({}, LRUCache(0), None):
    class C:
        def __init__(self):
            self.cache, self.condition, self.calls = cache, Condition(), 0
        @cachedmethod(lambda self: self.cache, condition=lambda self: self.condition)
        def get(self, k):
            self.calls += 1
            if self.calls == 1:
                raise ValueError('computation failed')
            return k
    obj = C()
    with ThreadPoolExecutor(4) as pool:
        fs = [pool.submit(obj.get, 1) for _ in range(4)]
        errors = 0
        for future in fs:
            try:
                assert future.result(5) == 1
            except ValueError:
                errors += 1
        assert errors == 1
print('Instance isolation, cache clearing during computation, and method failure checks passed')
